return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=2; plural=(n != 1 && n != 2 && n != 3 && (n%10 == 4 || n%10 == 6 || n%10 == 9));','language'=>'tl','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-26T16:59:17+00:00','po-revision-date'=>'2026-09-26T16:59:17+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'Ang pundasyon na paglabas ng muling ginawang Page Builder Sandwich: isang screen ng mga setting at Tungkol sa, isang front-end na output layer na walang footprint, at isang sample na content block.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Mga tagapagbigay ng AI','The makers of ChatGPT. A good all-rounder.'=>'Ang mga lumikha ng ChatGPT. Isang mahusay na panlahat.','The makers of Claude. Strong at writing and careful reasoning.'=>'Ang mga gumawa ng Claude. Mahusay sa pagsulat at maingat sa pangangatwiran.','Google\'s Gemini models. Fast and inexpensive.'=>'Ang mga modelo ng Gemini ng Google. Mabilis at mura.','A European AI company with fast, inexpensive models.'=>'Isang European AI company na may mabilis at murang mga modelo.','Low-cost models that are good at writing and code.'=>'Mga modelong mura na magaling sa pagsusulat at code.','One key for models from many different providers.'=>'Isang susi para sa mga modelo mula sa iba\'t ibang provider.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Anumang serbisyo na gumagana tulad ng API ng OpenAI, kabilang ang isang modelong tumatakbo sa iyong sariling computer o server.','General (used when nothing more specific is set)'=>'Pangkalahatan (ginagamit kapag walang nakatakdang mas tiyak)','Writing and rewriting'=>'Pagsusulat at muling pagsusulat','Translation'=>'Pagsasalin','Code and CSS'=>'Code at CSS','Sorry, you are not allowed to access this page.'=>'Paumanhin, hindi ka pinapayagang ma-access ang pahinang ito.','These settings are shared by every plugin that uses them: %s.'=>'Ang mga setting na ito ay ibinabahagi ng bawat plugin na gumagamit sa kanila: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Naka-encrypt ang iyong mga susi sa database ng site na ito at ipinapadala lamang sa provider na iyong pinili — hindi kailanman sa amin.','Step 1 of 2: choose an AI provider'=>'Hakbang 1 sa 2: pumili ng provider ng AI','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Nagdadala ka ng sarili mong key, kaya direktang nagbabayad ka sa provider para sa kung ano ang ginagamit mo. Hindi sigurado? Aluman sa mga ito ay maayos na gumagana; maaari kang magdagdag ng iba mamaya.','Next'=>'Susunod','Step 2 of 2: connect %s'=>'Hakbang 2 sa 2: ikonekta ang %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Ilagay ang address ng iyong serbisyong tugma sa OpenAI, na nagtatapos sa /v1. Kinakailangan lamang ang isang key kung humihingi nito ang serbisyo.','Open %s and sign in (or create a free account).'=>'Buksan ang %s at mag-sign in (o lumikha ng libreng account).','the %s API keys page'=>'ang %s pahina ng mga API key','Create a new key and copy it.'=>'Gumawa ng bagong key at kopyahin ito.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'I-paste ito sa ibaba at pindutin ang "Save and test". Nagpapadala kami ng isang maliit na kahilingan upang suriin kung gumagana ito.','Most providers need a little credit on the account before a key works: %s.'=>'Karamihan sa mga provider ay nangangailangan ng kaunting credit sa account bago gumana ang isang key: %s.','add credit'=>'magdagdag ng credit','← Choose a different provider'=>'← Pumili ng ibang provider','Address'=>'Address','Saved key ends in …%s — paste a new one to replace it'=>'Ang naka-save na key ay nagtatapos sa …%s — i-paste ang bago para mapalitan ito','Key (optional)'=>'Susing (opsyonal)','API key'=>'API key','Save and test'=>'I-save at subukan','Providers'=>'Mga Provider','Provider'=>'Tagapagbigay','Status'=>'Katayuan','Key'=>'Susi','Get a key'=>'Kumuha ng susi','Test'=>'Subukan','Remove'=>'Alisin','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Na-save sa mas bagong bersyon ng plugin: i-update ang plugin na ito, o ilagay muli ang key.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Hindi na mabubuksan ang nakasave na susi (nagbago ang mga security key ng site). Ilagay itong muli.','Not connected'=>'Hindi nakakonekta','Connected — last test passed %s'=>'Konektado — ang huling pagsubok ay pumasa %s','Last test failed: %s'=>'Nabigo ang huling pagsubok: %s','Connected — not tested yet'=>'Nakakonekta — hindi pa nasusubukan','Which model to use'=>'Aling modelo ang gagamitin','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ ang nagmamarka sa aming rekomendasyon para sa gawaing iyon. Kasama sa listahan ang bawat modelong magagamit ng iyong key, na direktang binabasa mula sa provider.','— Recommended for the provider —'=>'— Inirerekomenda para sa tagapagbigay —','Save models'=>'I-save ang mga modelo','Refresh the model lists from the providers'=>'I-refresh ang mga listahan ng modelo mula sa mga provider','best quality'=>'pinakamataas na kalidad','lowest cost'=>'pinakamababang gastos','fastest'=>'pinakamabilis','Add a model yourself'=>'Magdagdag ng modelo nang mag-isa','A model came out today? Paste its exact name to use it straight away.'=>'May lumabas na modelo ngayon? I-paste ang eksaktong pangalan nito para magamit agad.','Model name'=>'Pangalan ng modelo','Add model'=>'Magdagdag ng modelo','Recommended models list'=>'Listahan ng mga inirerekomendang modelo','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Hindi na-verify ang listahan ng mga inirerekomendang modelo, kaya walang ipinapakitang rekomendasyon. I-install muli ang plugin, o i-on ang mga pang-araw-araw na update sa ibaba.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Ang listahang ginagamit ay inilathala noong %s. Ang bawat pag-update ng plugin ay nagdadala ng bago.','Also check Zinn Digital® once a day for an updated list.'=>'Suriin din ang Zinn Digital® minsan sa isang araw para sa na-update na listahan.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Isang simpleng kahilingan sa pag-download lamang ang ipinapadala: walang susing kasama, walang address ng site, walang anuman tungkol sa iyong nilalaman. Ang listahan ay may lagda, at ang listahang nabigo sa pagsusuri ng lagda ay binabalewala.','Last checked %1$s: %2$s.'=>'Huling sinuri noong %1$s: %2$s.','Save, and check now if turned on'=>'I-save, at suriin ngayon kung naka-on','a newer list was installed'=>'na-install ang mas bagong listahan','already up to date'=>'napapanahon na</','the download failed the signature check and was ignored'=>'nabigo ang pag-download sa pagsusuri ng lagda at hindi pinansin','Zinn Digital® could not be reached; the current list stays in use'=>'Hindi maabot ang Zinn Digital®; nananatiling ginagamit ang kasalukuyang listahan','turned off'=>'naka-off','Open'=>'Buksan','Check their status page'=>'Suriin ang kanilang pahina ng katayuan','Open your billing page'=>'Buksan ang iyong pahina ng pagsingil','Open your API keys page'=>'Buksan ang iyong pahina ng mga API key','Open the AI settings'=>'Buksan ang mga setting ng AI','Sorry, you are not allowed to do that.'=>'Paumanhin, hindi ka pinapayagang gawin iyon.','Unknown provider.'=>'Hindi kilalang provider.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Ilagay ang address ng iyong serbisyo, halimbawa ay http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Hindi iyon mukhang API key. Kopyahin itong muli, nang walang mga espasyo.','Paste your API key first.'=>'I-paste muna ang iyong API key.','Key removed.'=>'Natanggal ang susi.','Models saved.'=>'Na-save ang mga modelo.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Ilagay ang eksaktong pangalan ng modelo, halimbawa kung paano ito isinulat sa dokumentasyon ng provider.','Added %s. Choose it under "Which model to use".'=>'Idinagdag ang %s. Piliin ito sa ilalim ng "Aling modelo ang gagamitin".','Model removed.'=>'Inalis ang modelo.','Daily updates are off. The list that came with the plugin is used.'=>'Naka-off ang mga araw-araw na update. Ginagamit ang listahang kasama ng plugin.','Checked: %s.'=>'Natiyak na: %s.','Model lists refreshed.'=>'Na-refresh na ang mga listahan ng modelo.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Ang iyong AI key ay nai-save ng mas bagong bersyon ng isa sa iyong mga plugin. I-update ang plugin na ito, o ilagay muli ang key sa mga setting ng AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Hindi na mabuksan ang iyong nakaimbak na AI key (nagbago ang mga security key ng site). Ilagay itong muli sa mga setting ng AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'Hindi pa naka-set up ang AI. Magdagdag ng key para sa isang AI provider sa mga setting ng AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Walang napiling modelo para sa gawaing ito. Pumili ng isa sa mga setting ng AI.','That AI provider is not supported by this version of the plugin.'=>'Hindi sinusuportahan ang AI provider na iyon ng bersyong ito ng plugin.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Hindi maabot ng site na ito ang iyong serbisyo sa AI. Suriin na ito ay tumatakbo at ang address nito ay naaabot mula sa iyong web server (ang isang serbisyo sa iyong sariling computer ay hindi maabot mula sa isang naka-host na site).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Hindi maabot ng site na ito ang %s. Suriin ang kanilang status page; kung gumagana sila, maaaring hinahararang ng iyong host ang mga papalabas na koneksyon, o mali ang address.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'Sabi ng %s na ang iyong account ay wala nang credit o quota. Magdagdag ng credit o itaas ang iyong limitasyon sa iyong account sa kanila, pagkatapos ay subukang muli.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'Hindi tinanggap ng %s ang iyong key. Maaaring mali ang pag-type nito, na-revoke, o nag-expire na. Gumawa ng bagong key at i-paste ito rito.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'Tinanggihan ng %s ang kahilingang ito para sa iyong key. Maaaring walang access ang key sa model o feature na ito, o kailangang i-verify ang iyong account.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Hindi available ang model na "%1$s" mula sa %2$s para sa iyong key. Pumili ng ibang modelo sa mga setting ng AI.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Ang iyong planong %2$s ay hindi kasama ang modelong "%1$s". Pumili ng ibang modelo sa mga setting ng AI, o i-upgrade ang iyong plano sa kanila.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'Nililimitahan ng %s kung gaano kaaga maaaring magpadala ng mga kahilingan ang iyong key. Maghintay ng isang minuto at subukang muli, o itaas sa kanila ang iyong limitasyon sa rate.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'Nakaranas ng problema ang %s ngayon (isang outage o labis na pagkarga sa kanilang bahagi). Walang mali sa iyong mga setting. Subukan muli maya-maya.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Nabigo ang kahilingan sa AI dahil sa dahilan na hindi namin natukoy. Subukan muli; kung magpapatuloy ito, makipag-ugnayan sa suporta kasama ang mga detalye sa ibaba.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Sumagot ang AI provider sa isang anyong hindi mabasa ng plugin na ito. Subukan muli; kung magpatuloy ito, pumumili ng ibang modelo o makipag-ugnayan sa suporta.','Custom (OpenAI-compatible)'=>'Pasadya (tugma sa OpenAI)','Save a key for this provider first.'=>'Mag-save muna ng key para sa provider na ito.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Gumagana ang iyong key, ngunit walang nakalistang text model para rito ang provider. Magdagdag ng modelo sa ibaba.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Konektado. Sinagot ni %1$s gamit ang %2$s. Handa nang gamitin ang iyong mga feature ng AI.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Hindi pinahihintulutan ang iyong tungkulin bilang user na gumamit ng AI sa site na ito. Mangyaring humingi ng tulong sa isang administrator.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Naabot na ng site na ito ang buwanang limitasyon sa paggastos para sa AI. Maaari itong itaas ng isang administrator sa mga setting ng AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Naabot na ng site na ito ang buwanang limitasyon nito para sa mga kahilingan sa AI. Maaari itong itaas ng isang administrator sa mga setting ng AI.','Usage and cost'=>'Paggamit at gastusin','The log, limits and role permissions apply to AI used through: %s.'=>'Nalalapat ang log, mga limitasyon, and mga pahintulot sa papel sa AI na ginamit sa pamamagitan ng: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Ang mga gastos ay tinatayang lamang, na kinuha mula sa mga inilathalang presyo; ang isang modelo na walang kilalang presyo ay binibilang na zero.','This month: %1$s requests, about %2$s.'=>'Ngayong buwan: %1$s na mga kahilingan, humigit-kumulang %2$s.','When'=>'Kailan','Who'=>'Sino','Used for'=>'Ginagamit para sa','Model'=>'Modelo','Tokens in / out'=>'Mga token na pumasok / lumabas','About'=>'Tungkol sa','Result'=>'Resultado','No AI requests have been made yet.'=>'Wala pang ginawang mga hiling sa AI.','Done'=>'Tapos na','Limits and permissions'=>'Mga limitasyon at pahintulot','Monthly spending limit (US dollars)'=>'Buwanang limitasyon sa paggastos (US dollars)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'I-left na walang laman para sa walang limitasyon. Humihinto ang AI para sa natitirang bahagi ng buwan kapag naabot na nito ang tinatayang gastusin.','Monthly request limit'=>'Buwanang limitasyon sa kahilingan','Leave empty for no limit.'=>'Hayaang blangko kung walang limitasyon.','Who may use AI'=>'Sino ang maaaring gumamit ng AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Huwag lagyan ng tsek para payagan ang lahat ng maaaring gumamit ng mga feature ng plugin na gumamit ng AI. Palaging magagamit ito ng mga administrator.','Save limits and permissions'=>'I-save ang mga limitasyon at pahintulot','Limits and permissions saved.'=>'Na-save na ang mga limitasyon at pahintulot.','Security error, please refresh the page and try again.'=>'Error sa seguridad, mangyaring i-refresh ang pahina at subukan muli.','Missing newsletter settings. Please contact the admin.'=>'Nawawala ang mga setting ng newsletter. Mangyaring kontakin ang admin.','Invalid newsletter settings. Please contact the admin.'=>'Hindi balido ang mga setting ng newsletter. Mangyaring makipag-ugnayan sa admin.','Invalid email address.'=>'Hindi wastong email address.','Too many attempts. Please try again in a few minutes.'=>'Napakaraming pagtatangka. Mangyaring subukan muli pagkalipas ng ilang minuto.','Something went wrong. Please contact the admin.'=>'May naganap na kamalian. Mangyaring makipag-ugnayan sa admin.','Map'=>'Mapa','Background video'=>'Video sa background','%1$s: %2$d font files stored, stylesheet %3$s'=>'%1$s: %2$d na file ng font ang nakaimbak, stylesheet %3$s','That family is not stored.'=>'Hindi nakaimbak ang pamilyang iyon.','Removed.'=>'Inalis.','That is not a valid font family name.'=>'Hindi iyan wastong pangalan ng pamilya ng font.','Google Fonts did not return that family. Check the name and try again.'=>'Hindi ibinalik ng Google Fonts ang pamilyang iyon. Suriin ang pangalan at subukang muli.','The font files could not be downloaded or saved. Check that the uploads folder is writable.'=>'Hindi na-download o nai-save ang mga file ng font. Suriin kung nasusulatan ang folder ng mga pag-upload.','The font stylesheet could not be saved. Check that the uploads folder is writable.'=>'Hindi na-save ang font stylesheet. Suriin kung nasusulatan ang folder ng mga upload.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Nawawala ang mga script ng screen ng admin mula sa kopya ng plugin na ito. I-reinstall ito mula sa isang inilabas na package.','This screen needs JavaScript.'=>'Nangangailangan ang screen na ito ng JavaScript.','Languages'=>'Mga Wika','Upgrade'=>'Mag-upgrade','Pricing'=>'Pagpepresyo','Start Trial'=>'Simulan ang Pagsubok','Account'=>'Account','Contact Us'=>'Makipag-ugnayan sa Amin','Affiliation'=>'Pangalan ng Kaanib','the kind of softwarePlugin'=>'Plugin','greetingHey %s,'=>'Kumusta %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Mag-opt in para makatanggap ng mga notification sa email para sa mga update sa seguridad at feature, nilalamang pang-edukasyon, at mga paminsan-minsang alok, at para magbahagi ng ilang pangunahing impormasyon tungkol sa kapaligiran ng WordPress. Makakatulong ito sa amin na gawing mas compatible ang %s sa iyong site at mas mahusay na magawa ang kailangan mo rito.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Mag-opt in para makatanggap ng mga notification sa email para sa mga update sa seguridad at feature, pang-edukasyon na nilalaman, at mga paminsan-minsang alok, at para magbahagi ng ilang pangunahing impormasyon tungkol sa kapaligiran ng WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Kung lalaktawan mo ito, ayos lang! Gagana pa rin nang maayos ang %1$s.','Allow & Continue'=>'Pahintulutan at Magpatuloy','verbSkip'=>'Laktawan','Skipping, please wait'=>'Laktawan, mangyaring maghintay','Continue'=>'Magpatuloy','Please wait'=>'Mangyaring maghintay','as activating pluginActivating'=>'Binabago','This will allow %s to'=>'Magbibigay-daan ito sa %s na','Privacy Policy'=>'Patakaran sa Pagkapribado','Terms of Service'=>'Mga Tuntunin ng Serbisyo','License Agreement'=>'Kasunduan sa Lisensya','Have a license key?'=>'Mayroon ka bang license key?','Activate License'=>'I-activate ang Lisensya','View Basic Profile Info'=>'Tingnan ang Pangunahing Impormasyon ng Profile','Your WordPress user\'s: first & last name, and email address'=>'Ang pangalan, apelyido, at email address ng iyong WordPress user','View Basic Website Info'=>'Tingnan ang Pangunahing Impormasyon ng Website','Homepage URL & title, WP & PHP versions, and site language'=>'Homepage URL at pamagat, mga bersyon ng WP at PHP, at wika ng site','View Basic %s Info'=>'Tingnan ang Pangunahing Impormasyon ng %s','Current %s & SDK versions, and if active or uninstalled'=>'Kasalukuyang %s & mga bersyon ng SDK, at kung aktivo o naka-uninstall','Newsletter'=>'Newsletter','Updates, announcements, marketing, no spam'=>'Mga update, anunsyo, marketing, walang spam','View Diagnostic Info'=>'Tingnan ang Diagnostic Info','WordPress & PHP versions, site language & title'=>'WordPress at PHP na mga bersyon, wika at pamagat ng site','View Plugins & Themes List'=>'Tingnan ang Listahan ng mga Plugin at Tema','Names, slugs, versions, and if active or not'=>'Mga pangalan, slug, bersyon, at kung aktibo o hindi','optional'=>'opsyonal','Never miss an important update'=>'Huwag palampasin ang anumang mahalagang update','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Ipinakilala namin ang opt-in na ito upang hindi mo kailanman mapalampas ang isang mahalagang update at matulungan kaming gawing mas angkop ang %s sa iyong site at mas mahusay sa paggawa ng kung ano ang kailangan mo rito.','Thank you for updating to %1$s v%2$s!'=>'Salamat sa pag-update sa %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Ang prefix ay dapat may 1 hanggang 8 na maliit na titik o numero, magsimula sa isang titik, at hindi dapat ipangalan sa plugin.','You are not allowed to edit this item.'=>'Hindi ka pinapayagang i-edit ang item na ito.','You are not allowed to do this.'=>'Hindi ka pinapayagang gawin ito.','Safe mode was turned off because it no longer matches your login. Reload the page.'=>'Na-off ang Safe mode dahil hindi na ito tumutugma sa iyong pag-login. I-reload ang pahina.','Only an administrator can use safe mode.'=>'Isang administrator lamang ang maaaring gumamit ng safe mode.','Safe mode needs a normal browser login.'=>'Kailangan sa safe mode ang normal na pag-login sa browser.','Safe mode could not be set up.'=>'Hindi nai-setup ang safe mode.','Safe mode needs write access to the wp-content/mu-plugins folder.'=>'Kailangan ng Safe mode ang write access sa wp-content/mu-plugins folder.','Safe mode could not write to the wp-content/mu-plugins folder.'=>'Hindi makasulat ang Safe mode sa folder ng wp-content/mu-plugins.','Sandwich Studio'=>'Sandwich Studio','That page does not exist, or it has been deleted.'=>'Wala ang pahinang iyon, o kaya ay tinanggal na ito.','Sorry, you are not allowed to edit this item in Sandwich Studio.'=>'Pasensya na, hindi ka pinapayagang i-edit ang item na ito sa Sandwich Studio.','Sandwich Studio is not built. Reinstall the plugin.'=>'Hindi binuo ang Sandwich Studio. I-reinstall ang plugin.','Add title'=>'Magdagdag ng pamagat','Type / to choose a block'=>'Mag-type ng / para pumili ng block','Loading Sandwich Studio…'=>'Naglo-load ang Sandwich Studio…','Sandwich Studio needs JavaScript. Use the normal editor instead.'=>'Kailangan ng Sandwich Studio ang JavaScript. Gamitin na lang ang normal na editor.','Edit “%s” with Sandwich Studio'=>'I-edit ang “%s” gamit ang Sandwich Studio','Edit with Sandwich Studio'=>'I-edit gamit ang Sandwich Studio','Blank canvas'=>'Blank canvas','A migration step is running right now. Try again in a minute.'=>'May tumatakbong hakbang sa paglipat sa ngayon. Subukang muli makalipas ang isang minuto.','Thank you for subscribing!'=>'Salamat sa pag-subscribe!','Something went wrong. Please contact the administrator.'=>'May nangyaring mali. Mangyaring makipag-ugnayan sa administrator.','Years'=>'Mga Taon','Months'=>'Mga Buwan','Weeks'=>'Mga Linggo','Days'=>'Mga Araw','Hours'=>'Oras','Minutes'=>'Minuto','Seconds'=>'Segundo','Go to slide %d'=>'Pumunta sa slide %d','You\'re already subscribed to our newsletter'=>'Nakapag-subscribe ka na sa aming newsletter','Email address is already subscribed.'=>'Nakarehistro na ang email address.','MailPoet plugin not found. Please contact the admin.'=>'Hindi nakita ang MailPoet plugin. Mangyaring makipag-ugnayan sa admin.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Binuo ni Neil Lock, CEO ng Zinn Digital® Ltd','Version %s'=>'Bersyon %s','Page Builder Sandwich website'=>'Website ng Page Builder Sandwich','Zinn Digital® website'=>'website ng Zinn Digital®','Settings saved.'=>'Naka-save ang mga setting.','See the Pro plans and pricing'=>'Tingnan ang mga Pro plan at pagpepresyo','Front-end output'=>'Front-end output','Class name prefix'=>'Prefix ng pangalan ng klase','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Ang bawat pangalan ng klase na ipinrint ng plugin sa iyong mga pahina ay nagsisimula sa prefix na ito, kaya hindi inilalantad ng mga pahina kung aling plugin ang gumawa sa mga ito. 1 hanggang 8 na maliit na titik o numero, na nagsisimula sa isang titik.','Save'=>'I-save','Beta updates'=>'Mga beta na update','This site receives beta versions as updates.'=>'Ang site na ito ay tumatanggap ng mga beta na bersyon bilang mga update.','This site receives stable versions only.'=>'Tumatanggap lamang ang site na ito ng mga matatag na bersyon.','Change this on the Account page'=>'Baguhin ito sa pahina ng Account','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Inaalok ang mga beta bersyon sa mga lisensyadong Pro installation na konektado sa kanilang account. Kapag nakakonekta na, maaari kang sumali mula sa pahina ng Account.','The request converting this post stopped before it finished, so the post was skipped. Open it to convert it, or convert it again from here.'=>'Huminto ang kahilingang nag-a-convert sa post na ito bago ito natapos, kaya lumaktaw ang post. Buksan ito para i-convert, o i-convert itong muli mula rito.','There is no backup of this post to restore.'=>'Walang backup ang post na ito na maaaring i-restore.','The converted content could not be saved.'=>'Hindi nai-save ang na-convert na nilalaman.','Unknown error.'=>'Hindi kilalang error.','No legacy content has been checked yet.'=>'Wala pang nasusuring lumang nilalaman.','Restoring legacy content: %1$d of %2$d posts.'=>'Pagpapanumbalik ng lumang nilalaman: %1$d sa %2$d na post.','Converting legacy content: %1$d of %2$d posts.'=>'Pag-convert ng lumang nilalaman: %1$d sa %2$d na post.','Undo finished: %1$d restored, %2$d failed.'=>'Tapos na ang pagkansela: %1$d ang naibalik, %2$d ang nabigo.','Conversion finished: %1$d converted, %2$d unchanged, %3$d failed.'=>'Tapos na ang conversion: %1$d ang na-convert, %2$d ang hindi nagbago, %3$d ang nabigo.','Legacy content'=>'Legacy na nilalaman','Pages made with earlier versions of Page Builder Sandwich are converted to blocks in the background. Every post is backed up first, so each conversion can be undone.'=>'Ang mga pahinang ginawa gamit ang mga mas lumang bersyon ng Page Builder Sandwich ay kino-convert sa mga bloke sa background. Naka-back up muna ang bawat post, kaya puwedeng i-undo ang bawat conversion.','%d post still holds legacy content.'=>'%d post ay nagtataglay pa rin ng lumang nilalaman.' . "\0" . 'Mayroong %d na post na naglalaman pa rin ng lumang nilalaman.','%d post has a backup.'=>'May backup ang %d na post.' . "\0" . '%d na post ang may backup.','%d post could not be handled'=>'Hindi naproseso ang %d na post' . "\0" . 'Hindi mapangasiwaan ang %d na mga post','Post %d'=>'Post %d','Conversion started. It continues in the background; you can leave this page.'=>'Nagsimula na ang conversion. Nagpapatuloy ito sa background; maaari mo nang lisanin ang pahinang ito.','Convert legacy content'=>'I-convert ang lumang nilalaman','Restore every converted post to its legacy content? Changes made to those posts since they were converted will be lost.'=>'Ibalik ba ang bawat na-convert na post sa lumang nilalaman nito? Mawawala ang mga pagbabagong ginawa sa mga post na iyon mula nang ma-convert ang mga ito.','Undo started. It continues in the background; you can leave this page.'=>'Sinimulan na ang Pag-undo. Nagpapatuloy ito sa background; maaari mong lisanin ang pahinang ito.','Undo all conversions'=>'I-undo ang lahat ng mga pagbabago','Shortcode tag'=>'Shortcode tag','Use letters, numbers, dashes and underscores only.'=>'Gumamit lamang ng mga titik, numero, gitling, at underscore.','Attribute name'=>'Pangalan ng attribute','Add attribute'=>'Magdagdag ng attribute','Content'=>'Nilalaman','Shortcode'=>'Shortcode','Choose a shortcode tag in the block settings.'=>'Pumili ng shortcode tag sa mga setting ng block.','The "%s" control from the old editor is not available in the block editor. Enter the value as text.'=>'Ang "%s" control mula sa lumang editor ay hindi available sa block editor. Ilagay ang value bilang text.','Choose image'=>'Pumili ng larawan','Choose file'=>'Pumili ng file','— Default —'=>'— Default —','Advanced styling'=>'Abalang istilo','Inline CSS'=>'Inline CSS','CSS declarations, for example: min-height: 380px; background-color: #333'=>'Mga deklarasyon sa CSS, halimbawa: min-height: 380px; background-color: #333','Effects (legacy classes)'=>'Mga Epekto (mga lumang klase)','Space-separated effect names carried over from older versions, for example: hover-shadow'=>'Mga pangalan ng epekto na pinaghihiwalay ng espasyo mula sa mga lumang bersyon, halimbawa: hover-shadow','Row'=>'Hilera','Width'=>'Lapad','Content width'=>'Lapad ng nilalaman','Full width'=>'Buong lapad','Full width, content kept in the middle'=>'Buong lawak, ang nilalaman ay nananatili sa gitna','Link'=>'I-link','Link address'=>'Address ng link','Open in a new tab'=>'Buksan sa isang bagong tab','Link relationship'=>'Relasyon ng link','Alignment'=>'Pagkakahanay','None'=>'Wala','Left'=>'Kaliwa','Centre'=>'Gitna','Right'=>'Kanan','Button text'=>'Teksto ng pindutan','Add text…'=>'Magdagdag ng teksto…','Icon'=>'Icon','SVG markup'=>'SVG markup','Scripts, links and external references are removed before the icon is shown.'=>'Ang mga script, link, at mga panlabas na sanggunian ay inaalis bago ipakita ang icon.','Accessible label'=>'Madalasang label','Leave empty for a decorative icon.'=>'Iwanang blangko para sa pampalamuting icon.','Paste SVG markup in the block settings.'=>'I-paste ang SVG markup sa mga setting ng block.','New setting name'=>'Bagong pangalan ng setting','For example: title or text'=>'Halimbawa: pamagat o teksto','Add setting'=>'Magdagdag ng setting','Widget'=>'Widget','Choose a widget'=>'Pumili ng widget','Widget area'=>'Lugar ng widget','Choose a widget area'=>'Pumili ng isang widget area','This image has no width and height, so the page will jump when it loads. Choose it from the Media Library, or set its width and height.'=>'Ang larawang ito ay walang lapad at taas, kaya tatalon ang pahina kapag nag-load ito. Piliin ito mula sa Media Library, o itakda ang lapad at taas nito.','This video is not from the Media Library, so its size is unknown and the page will jump when it loads. Upload it to the Media Library instead.'=>'Ang videong ito ay hindi mula sa Media Library, kaya hindi alam ang laki nito at lundag ang pahina kapag nag-load ito. Mag-upload na lamang nito sa Media Library.','An image, video or frame in this HTML has no width and height, so the page will jump when it loads. Add width and height attributes to it.'=>'Ang isang larawan, video o frame sa HTML na ito ay walang lapad at taas, kaya tatalon ang pahina kapag nag-load ito. Magdagdag ng mga attribute na width at height dito.','This embed resizes itself after it loads, which moves the content below it. Give it room or place it lower on the page.'=>'Nagre-resize ang embed na ito pagkatapos itong mag-load, na nagiging sanhi ng paggalaw ng content sa ibaba nito. Bigyan ito ng espasyo o ilagay ito nang mas mababa sa pahina.','Layout shift'=>'Paglipat ng layout','Heading'=>'Heading','Text'=>'Text','Style'=>'Estilo','Plain'=>'Karaniwan','Accent'=>'Aksento','No languages to switch between. The switcher appears when a translation plugin lists two or more languages.'=>'Walang mga wikang mapagpipilian. Lumilitaw ang switcher kapag naglista ang isang translation plugin ng dalawa o higit pang wika.','Switcher'=>'Switcher','Show the current language'=>'Ipakita ang kasalukuyang wika','%s is also editing this page. Saving may overwrite their changes.'=>'Ginagawa rin ni %s ang pahinang ito. Ang pag-save ay maaaring mag-overwrite sa kanilang mga pagbabago.','Block library'=>'Aklatan ng block','Layers'=>'Mga Layer','Close panel'=>'Isara ang panel','Page canvas'=>'Canvas ng pahina','Revisions'=>'Mga Rebisyon','Block settings'=>'I-block ang mga setting','Add block: %s'=>'Magdagdag ng block: %s','(no title)'=>'(walang pamagat)','Open in Studio: %s'=>'Buksan sa Studio: %s','Undo'=>'I-undo','Redo'=>'Ulitin','Show or hide layers'=>'Ipakita o itago ang mga layer','Show or hide the block library'=>'Ipakita o itago ang library ng block','Show revisions'=>'Ipakita ang mga rebisyon','Open the normal editor'=>'Buksan ang karaniwang editor','Keyboard shortcuts'=>'Mga shortcut sa keyboard','Preview: desktop'=>'Pasilip: desktop','Preview: tablet'=>'Pasulyap: tablet','Preview: mobile'=>'Paunang-tingin: mobile','Copy style of the selected block'=>'Kopyahin ang estilo ng napiling bloke','Paste style onto the selected block'=>'Idikit ang estilo sa napiling bloke','Copy the selected section'=>'Kopyahin ang napiling bahagi','Paste a copied section'=>'I-paste ang kinopong seksyon','Turn off safe mode'=>'Patayin ang safe mode','Turn on safe mode (other plugins off, for you, in Studio only)'=>'I-on ang safe mode (naka-off ang iba pang plugin, para sa iyo, sa Studio lang)','Published'=>'Nai-publish na','Scheduled'=>'Naka-iskedyul','Pending review'=>'Nakabinbin ang pagsusuri','Private'=>'Pribado','Draft'=>'Burador','All changes saved'=>'Na-save ang lahat ng mga pagbabago','Saving…'=>'Nag-iingat…','Autosaving…'=>'Awtomatikong nagse-save…','Unsaved changes'=>'Mga hindi nakaimbak na pagbabago','autosaved'=>'kusang-na-save','Desktop preview'=>'Preview sa desktop','Tablet preview'=>'Preview ng tablet','Mobile preview'=>'Mobile na preview','Studio toolbar'=>'Toolbar ng Studio','Back to the normal editor'=>'Bumalik sa normal na editor','Page title'=>'Pamagat ng pahina','Preview width'=>'Lapad ng paunang tingin','Command palette'=>'Palette ng command','View page (opens in a new tab)'=>'Tingnan ang pahina (bubukas sa bagong tab)','Update'=>'I-update','Save draft'=>'I-save ang draft','Publish'=>'I-publish','Restore unsaved changes?'=>'Ibalik ang mga hindi nai-save na pagbabago?','This page has changes that were never saved. They were kept in this browser:'=>'Ang pahinang ito ay may mga pagbabago na hindi kailanman na-save. Ang mga ito ay itinago sa browser na ito:','This page has a newer autosave than the saved version:'=>'May mas bagong autosave ang pahinang ito kaysa sa nakaimbak na bersyon:','Restore unsaved changes'=>'Ibalik ang mga hindi na-save na pagbabago','Discard'=>'Itapon','Revisions could not be loaded.'=>'Hindi ma-load ang mga rebisyon.','Revision restored. Save to keep it, or undo to go back.'=>'Naibalik ang rebisyon. I-save para panatilihin ito, o i-undo para bumalik.','Close revisions'=>'Isara ang mga rebisyon','No revisions yet. Each save makes one.'=>'Wala pang mga rebisyon. Ang bawat pag-save ay lumilikha ng isa.','Revision from %s'=>'Rebisyon mula sa %s','Restore this revision'=>'Ibalik ang rebisyong ito','Cancel'=>'Kanselahin','Safe mode could not be changed.'=>'Hindi mabago ang safe mode.','Safe mode is on.'=>'Naka-on ang safe mode.','%d other plugin is switched off, for you and in Sandwich Studio only. The live site and other users are not affected.'=>'Naka-off ang %d isa pang plugin, para sa iyo at sa Sandwich Studio lang. Hindi apektado ang live na site at ang iba pang mga user.' . "\0" . 'Naka-off ang iba pang %d na plugin para sa iyo at sa Sandwich Studio lang. Hindi apektado ang live site at ang iba pang mga user.','Safe mode: switch other plugins off in Studio, for you only'=>'Safe mode: i-off ang iba pang mga plugin sa Studio, para sa iyo lang','Safe mode'=>'Safe mode','Save your changes.'=>'I-save ang iyong mga pagbabago.','Undo your last change.'=>'I-undo ang iyong huling pagbabago.','Redo your last undo.'=>'Gawing muli ang iyong huling pag-undo.','Show or hide the layers panel.'=>'Ipakita o itago ang panel ng mga layer.','Display these keyboard shortcuts.'=>'Ipakita ang mga shortcut sa keyboard na ito.','Select a block first.'=>'Pumili muna ng isang bloke.','Style copied. Paste it onto any block, on this site or another.'=>'Nakopya ang estilo. I-paste ito sa anumang block, sa site na ito o sa iba pa.','The browser refused to copy.'=>'Tumanggi ang browser na kopyahin ito.','Section copied. Paste it into any page, on this site or another.'=>'Kopya na ang seksiyon. I-paste ito sa anumang pahina, sa site na ito o sa iba.','The clipboard does not hold a style copied from Sandwich Studio.'=>'Walang estilo na nakopya mula sa Sandwich Studio sa clipboard.','Style pasted onto %d block.'=>'Naka-paste ang estilo sa %d block.' . "\0" . 'Nailapat ang estilo sa %d na mga bloke.','That style does not fit the selected block.'=>'Hindi kasya ang istilong iyon sa napiling bloke.','The clipboard does not hold a copied section.'=>'Walang kinopyang seksyon ang clipboard.','Section pasted.'=>'Na-paste ang seksyon.','Paste style'=>'I-paste ang estilo','Paste section'=>'I-paste ang seksyon','Press Ctrl+V (or Cmd+V on a Mac) here to paste'=>'Pindutin ang Ctrl+V (o Cmd+V sa Mac) dito para i-paste','Copy style'=>'Kopyahin ang istilo','Copy section'=>'Kopyahin ang seksyon','Edit in Sandwich Studio'=>'I-edit sa Sandwich Studio','Saving failed. Check your connection and try again; your changes are kept in this browser.'=>'Nabigo ang pag-save. Suriin ang iyong koneksyon at subukan muli; nakatago ang iyong mga pagbabago sa browser na ito.','Published.'=>'Naka-publish na.','Saved.'=>'Na-save na.','block titleButton link'=>'Link ng button','block descriptionA link styled as a button.'=>'Isang link na naka-istilo bilang button.','block keywordbutton'=>'butones','block keywordlink'=>'link','block keywordcall to action'=>'panawagan sa pagkilos','block titleColumn'=>'Kolum','block descriptionA column inside a row. It can hold any block.'=>'Isang haligi sa loob ng isang hilera. Maaari itong maglaman ng anumang bloke.','block keywordcolumn'=>'kolum','block keywordlayout'=>'layout','block titleLanguage switcher (sample)'=>'Tagapagpalit ng Wika (sample)','block descriptionLists the site\'s languages from the translation plugin, when one is active. It renders nothing otherwise.'=>'Ilista ang mga wika ng site mula sa plugin ng pagsasalin, kapag aktibo ito. Hindi ito nag-render ng anuman kung hindi man.','block keywordlanguage'=>'wika','block keywordswitcher'=>'panlipat','block titleSample content'=>'Halimbawang nilalaman','block descriptionA heading and a paragraph, rendered with neutral class names. It is the reference block for the translation contract.'=>'Isang heading at isang talata, na naka-render na may mga neutral na pangalan ng klase. Ito ang sangguniang bloke para sa kontrata sa pagsasalin.','block keywordsample'=>'sampol','block keywordtext'=>'teksto','block titleIcon'=>'Icon','block descriptionAn SVG icon. The markup is cleaned before it is shown.'=>'Isang icon na SVG. Nililinis ang markup bago ito ipakita.','block keywordicon'=>'ikon','block keywordsvg'=>'svg','block titleRow'=>'Hilera','block descriptionA row of columns. Stays readable if the plugin is ever turned off.'=>'Isang hilera ng mga kolum. Nananatiling nababasa kung sakaling i-off ang plugin.','block keywordrow'=>'hilera','block keywordcolumns'=>'mga kolum','block titleShortcode (add-on)'=>'Shortcode (add-on)','block descriptionA shortcode from an add-on written for the classic Page Builder Sandwich editor, with the settings the add-on declared.'=>'Isang shortcode mula sa isang add-on na isinulat para sa klasikong editor ng Page Builder Sandwich, kasama ang mga setting na idineklara ng add-on.','block keywordshortcode'=>'shortcode','block keywordadd-on'=>'add-on','block titleWidget area'=>'Lugar ng widget','block descriptionShows the widgets in one of the theme\'s widget areas.'=>'Ipinapakita ang mga widget sa isa sa mga lugar ng widget ng tema.','block keywordsidebar'=>'sidebar','block keywordwidget area'=>'lugar ng widget','block titleWidget'=>'Widget','block descriptionShows one of the site\'s registered classic widgets.'=>'Ipinapakita ang isa sa mga rehistradong klasikong widget ng site.','block keywordwidget'=>'widget']];